        function isNumberKey(evt) {
            const charCode = evt.which ? evt.which : evt.keyCode;
            if (charCode < 48 || charCode > 57) return false;
            return true;
        }
        function checkValidity() {
            const grid = document.getElementById("sudokuGrid").cells;
            const isValid = grid.every(cell => cell.value && cell.value.length === 1 && isNumberKey(cell.value.charCodeAt(0)));
            if (isValid) {
                alert("Parabene! Hai completato la soluzione.");
                document.getElementById("sudokuGrid").style.backgroundColor = "green";
            } else {
                alert("Completati tutti i valori!");
                document.getElementById("sudokuGrid").style.backgroundColor = "red";
