            const grid = document.getElementById("sudokuGrid").cells;
            const selectedCell = event.target;
            if (selectedCell.value || selectedCell.value === "0") {
                selectedCell.value = "";
            }
            for (let i = 0; i < 9; i++) {
                for (let j = 0; j < 9; j++) {
                    const cell = document.getElementById(`${i + 1} ${j + 1}`);
