                }
            }
        }
        function resetGrid() {
            const grid = document.getElementById("sudokuGrid").cells;
            for (let i = 0; i < 9; i++) {
                for (let j = 0; j < 9; j++) {
                    const cell = document.getElementById(`${i + 1} ${j + 1}`);
                    cell.value = "";
                }
            }
            document.getElementById("sudokuGrid").style.backgroundColor = "white";
        }
